INSERT INTO ingredient_dish_mappings
    (mapping_id, ingredient_food_id, dish_id, priority, active, created_at, updated_at)
SELECT seed.mapping_id, food.food_id, seed.dish_id, seed.priority,
       TRUE, CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6)
FROM (
    SELECT '20000000-0000-5000-8000-000000000001' mapping_id, '귀리' ingredient_name, '10000000-0000-5000-8000-000000000001' dish_id, 1 priority
    UNION ALL SELECT '20000000-0000-5000-8000-000000000002', '귀리', '10000000-0000-5000-8000-000000000002', 2
    UNION ALL SELECT '20000000-0000-5000-8000-000000000003', '귀리', '10000000-0000-5000-8000-000000000003', 3
    UNION ALL SELECT '20000000-0000-5000-8000-000000000004', '감자', '10000000-0000-5000-8000-000000000004', 1
    UNION ALL SELECT '20000000-0000-5000-8000-000000000005', '감자', '10000000-0000-5000-8000-000000000005', 2
    UNION ALL SELECT '20000000-0000-5000-8000-000000000006', '감자', '10000000-0000-5000-8000-000000000006', 3
    UNION ALL SELECT '20000000-0000-5000-8000-000000000007', '고구마', '10000000-0000-5000-8000-000000000007', 1
    UNION ALL SELECT '20000000-0000-5000-8000-000000000008', '고구마', '10000000-0000-5000-8000-000000000008', 2
    UNION ALL SELECT '20000000-0000-5000-8000-000000000009', '고구마', '10000000-0000-5000-8000-000000000009', 3
