    UNION ALL SELECT '20000000-0000-5000-8000-000000000023', '당근', '10000000-0000-5000-8000-000000000023', 2
    UNION ALL SELECT '20000000-0000-5000-8000-000000000024', '당근', '10000000-0000-5000-8000-000000000024', 3
    UNION ALL SELECT '20000000-0000-5000-8000-000000000025', '파프리카', '10000000-0000-5000-8000-000000000025', 1
    UNION ALL SELECT '20000000-0000-5000-8000-000000000026', '파프리카', '10000000-0000-5000-8000-000000000026', 2
